import os
tot = 0
for root, dirs, files in os.walk('data'):
    for f in files:
        p = os.path.join(root, f)
        if os.path.islink(p) or not os.path.isfile(p) or p.endswith('big.sparse'):
            continue
        try:
            b = open(p, 'rb').read()
        except OSError as e:
            print('skip unreadable', p)
            continue
        c = sum(1 for line in b.split(b"\n") if b"invoice" in line)
        print(c, p)
        tot += c
print('TOTAL(excl big):', tot)
PY
